def esc(t):
    t = t.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
    t = t.replace("\\'", "'").replace("'", "\\'").replace('"','\\"')
    return t
dirs=['values','values-mk','values-de','values-ru']
for i,d in enumerate(dirs):
    os.makedirs(f'{R}/{d}',exist_ok=True)
    out=['<?xml version="1.0" encoding="utf-8"?>','<!-- Keep the four strings.xml files in step: same keys, same format arguments (AGENTS.md). -->','<resources>']
    for k,v in S.items():
        extra = ' translatable="false"' if (k=='app_name' and i==0) else ''
        out.append(f'    <string name="{k}">{esc(v[i])}</string>')
    for k,v in P.items():
        out.append(f'    <plurals name="{k}">')
        for q,t in v[i].items():
            out.append(f'        <item quantity="{q}">{esc(t)}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    open(f'{R}/{d}/strings.xml','w').write('\n'.join(out)+'\n')
print(len(S), 'strings')
